      "keystrokes": "cat > /tmp/test_full.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define NV 50257
#define NC 1024
#define ND 768
#define NL 12
#define NH 12
#define HD 64
static float*W; static long N;
void st(long off,int cnt,const char*name){
 double s=0,ss=0,mn=1e9,mx=-1e9;
 for(int i=0;i<cnt;i++){double x=W[off+i];s+=x;ss+=x*x;if(x<mn)mn=x;if(x>mx)mx=x;}
 printf("%-16s off=%-12ld cnt=%-7d mean=%.5f sd=%.5f min=%.5f max=%.5f\n",name,off,cnt,s/cnt,sqrt(ss/cnt-s/cnt*s/cnt),mn,mx);
}
void ln(float*o,float*x,float*g,float*b,int ga){
 float m=0;for(int i=0;i<ND;i++)m+=x[i];m/=ND;
 float v=0;for(int i=0;i<ND;i++){float d=x[i]-m;v+=d*d;}v/=ND;
 float s=1.0f/sqrtf(v+1e-5f);
 for(int i=0;i<ND;i++)o[i]=(x[i]-m)*s*(g[i]+ga)+b[i];
}
float gelu(float x){return 0.5f*x*(1.0f+erff(x*0.70710678118654752f));}
void fwd(int*toks,int T,int trans,int ga,float*lgs){
 long wteoff=N-38597376,wpeoff=N-38597376-786432,lnfgoff=N-38597376-786432-768,lnfboff=N-38597376-786432-1536;
 float*wte=W+wteoff,*wpe=W+wpeoff;
 long nblk[12]; long bloffs[12]={0,7087872,14175744,21263616,28351488,35439360,42527232,49615104,56702976,63790848,70878720,77966592};
 int blnum[12]={0,1,10,11,2,3,4,5,6,7,8,9};
 for(int i=0;i<12;i++)nblk[blnum[i]]=bloffs[i];
 long catb=0,catw=2304,cpjb=1771776,cpjw=1772544,ln1b=2362368,ln1g=2363136,ln2b=2363904,ln2g=2364672,cfcb=2365440,cfcw=2368512,cpcb=4727808,cpcw=4728576;
 static float x[NC][ND],h[NC][ND],q[NC][ND],k[NC][ND],v[NC][ND],att[NC][ND],qkv[2304],h1[3072],tmp[ND];
 for(int t=0;t<T;t++)for(int i=0;i<ND;i++)x[t][i]=wte[toks[t]*ND+i]+wpe[t*ND+i];
 for(int l=0;l<NL;l++){
  long b=nblk[l];
  float*g1=W+b+ln1g,*b1=W+b+ln1b,*cw=W+b+catw,*cb=W+b+catb,*pw=W+b+cpjw,*pb=W+b+cpjb;
  float*g2=W+b+ln2g,*b2=W+b+ln2b,*fw=W+b+cfcw,*fb=W+b+cfcb,*pw2=W+b+cpcw,*pb2=W+b+cpcb;
  for(int t=0;t<T;t++)ln(h[t],x[t],g1,b1,ga);
  for(int t=0;t<T;t++){
   for(int j=0;j<2304;j++){float s=cb[j];for(int i=0;i<ND;i++)s+=h[t][i]*(trans?cw[j*ND+i]:cw[i*2304+j]);qkv[j]=s;}
   memcpy(q[t],qkv,ND*4);memcpy(k[t],qkv+ND,ND*4);memcpy(v[t],qkv+2*ND,ND*4);
  }
  for(int hi=0;hi<NH;hi++)for(int t=0;t<T;t++){
   float sc[NC];
   for(int t2=0;t2<=t;t2++){float s=0;for(int d=0;d<HD;d++)s+=q[t][hi*HD+d]*k[t2][hi*HD+d];sc[t2]=s*0.125f;}
   float mx=sc[0];for(int t2=1;t2<=t;t2++)if(sc[t2]>mx)mx=sc[t2];
   float sm=0;for(int t2=0;t2<=t;t2++){sc[t2]=expf(sc[t2]-mx);sm+=sc[t2];}
   for(int t2=0;t2<=t;t2++)sc[t2]/=sm;
   for(int d=0;d<HD;d++){float s=0;for(int t2=0;t2<=t;t2++)s+=sc[t2]*v[t2][hi*HD+d];att[t][hi*HD+d]=s;}
  }
  for(int t=0;t<T;t++){
   for(int j=0;j<ND;j++){float s=pb[j];for(int i=0;i<ND;i++)s+=att[t][i]*(trans?pw[j*ND+i]:pw[i*ND+j]);tmp[j]=s;}
   for(int i=0;i<ND;i++)x[t][i]+=tmp[i];
  }
  for(int t=0;t<T;t++){
   ln(h[t],x[t],g2,b2,ga);
   for(int j=0;j<3072;j++){float s=fb[j];for(int i=0;i<ND;i++)s+=h[t][i]*(trans?fw[j*ND+i]:fw[i*3072+j]);h1[j]=gelu(s);}
   for(int j=0;j<ND;j++){float s=pb2[j];for(int i=0;i<3072;i++)s+=h1[i]*(trans?pw2[j*3072+i]:pw2[i*ND+j]);tmp[j]=s;}
   for(int i=0;i<ND;i++)x[t][i]+=tmp[i];
  }
 }
 float*lg=W+lnfgoff,*lb=W+lnfboff;
 ln(tmp,x[T-1],lg,lb,ga);
 for(int i=0;i<NV;i++){float s=0;for(int j=0;j<ND;j++)s+=tmp[j]*wte[i*ND+j];lgs[i]=s;}
}
int main(){
 FILE*f=fopen("gpt2-124M.ckpt","rb");fseek(f,0,SEEK_END);N=ftell(f)/4;fseek(f,0,SEEK_SET);
 W=malloc(N*4);if(fread(W,4,N,f)!=N)return 1;fclose(f);
 long wteoff=N-38597376,wpeoff=N-38597376-786432;
 st(wteoff,38597376,"wte_full"); st(wpeoff,786432,"wpe_full");
 int toks1[]={464}; int toks2[]={464,2361,6381}; // The quick brown
 static float lgs[NV];
 for(int trans=0;trans<2;trans++)for(int ga=0;ga<2;ga++){
  printf("\n=== trans=%d gadd=%d ===\n",trans,ga);
  fwd(toks1,1,trans,ga,lgs);
  printf("The:");
  for(int r=0;r<5;r++){int b=0;for(int i=1;i<NV;i++)if(lgs[i]>lgs[b])b=i;printf(" %d(%.2f)",b,lgs[b]);lgs[b]=-1e9;}
  printf("\n");
  fwd(toks2,3,trans,ga,lgs);
  printf("The quick brown:");
  for(int r=0;r<5;r++){int b=0;for(int i=1;i<NV;i++)if(lgs[i]>lgs[b])b=i;printf(" %d(%.2f)",b,lgs[b]);lgs[b]=-1e9;}
  printf("\n");
 }
 return 0;
}
